#include <utility>
#include <typeinfo>
#include <iostream>

void check_type(double) { std::cout << "(double)\n"; }
void check_type(float) { std::cout << "(float)\n"; }

int main() {
    // 1.0 is double, forcing pair<int, double>
    auto p1 = std::make_pair(1, 1.0);
    std::cout << "p1 type: "; check_type(p1.second);

    // 1.0f is explicitly float, forcing pair<int, float>
    auto p2 = std::make_pair(1, 1.0f);
    std::cout << "p2 type: "; check_type(p2.second);
}
